/**
 * Event Bus - A simple in-memory pub/sub system for inter-service communication
 */

export type EventCallback = (payload: Record<string, unknown>) => void;

export class EventBus {
  private subscribers: Map<string, EventCallback[]> = new Map();

  /**
   * Subscribe to an event
   */
  subscribe(eventName: string, callback: EventCallback): void {
    if (!this.subscribers.has(eventName)) {
      this.subscribers.set(eventName, []);
    }
    this.subscribers.get(eventName)!.push(callback);
  }

  /**
   * Publish an event to all subscribers
   */
  publish(eventName: string, payload: Record<string, unknown>): void {
    const callbacks = this.subscribers.get(eventName);
    if (callbacks) {
      callbacks.forEach((callback) => {
        try {
          callback(payload);
        } catch (error) {
          console.error(`Error in event handler for ${eventName}:`, error);
        }
      });
    }
  }
}

export const eventBus = new EventBus();

/**
 * User Service - Manages users
 */

export interface User {
  id: string;
  name: string;
  email: string;
}

export class UserService {
  private users: Map<string, User> = new Map();
  private nextId = 1;

  /**
   * Create a new user
   */
  createUser(name: string, email: string): User {
    const id = `user-${this.nextId++}`;
    const user: User = { id, name, email };
    this.users.set(id, user);
    return user;
  }

  /**
   * Get a user by ID
   */
  getUser(id: string): User | null {
    return this.users.get(id) || null;
  }

  /**
   * Get all users
   */
  getAllUsers(): User[] {
    return Array.from(this.users.values());
  }

  /**
   * Update a user
   */
  updateUser(id: string, updates: Partial<User>): User | null {
    const user = this.users.get(id);
    if (!user) return null;

    if (updates.name !== undefined) user.name = updates.name;
    if (updates.email !== undefined) user.email = updates.email;

    return user;
  }

  /**
   * Delete a user
   */
  deleteUser(id: string): boolean {
    return this.users.delete(id);
  }

  /**
   * Check if a user exists
   */
  userExists(id: string): boolean {
    return this.users.has(id);
  }
}

export const userService = new UserService();

/**
 * Project Service - Manages projects and their members
 */

import { userService } from './user-service';

export interface Project {
  id: string;
  name: string;
  description: string;
  members: string[]; // User IDs
}

export class ProjectService {
  private projects: Map<string, Project> = new Map();
  private nextId = 1;

  /**
   * Create a new project
   */
  createProject(name: string, description: string): Project {
    const id = `project-${this.nextId++}`;
    const project: Project = { id, name, description, members: [] };
    this.projects.set(id, project);
    return project;
  }

  /**
   * Get a project by ID
   */
  getProject(id: string): Project | null {
    return this.projects.get(id) || null;
  }

  /**
   * Get all projects
   */
  getAllProjects(): Project[] {
    return Array.from(this.projects.values());
  }

  /**
   * Update a project
   */
  updateProject(id: string, updates: Partial<Project>): Project | null {
    const project = this.projects.get(id);
    if (!project) return null;

    if (updates.name !== undefined) project.name = updates.name;
    if (updates.description !== undefined) project.description = updates.description;

    return project;
  }

  /**
   * Delete a project
   */
  deleteProject(id: string): boolean {
    return this.projects.delete(id);
  }

  /**
   * Add a member to a project
   */
  addMember(projectId: string, userId: string): Project | null {
    const project = this.projects.get(projectId);
    if (!project) return null;

    // Verify the user exists
    if (!userService.userExists(userId)) return null;

    // Don't add duplicate members
    if (!project.members.includes(userId)) {
      project.members.push(userId);
    }

    return project;
  }

  /**
   * Remove a member from a project
   */
  removeMember(projectId: string, userId: string): Project | null {
    const project = this.projects.get(projectId);
    if (!project) return null;

    project.members = project.members.filter((id) => id !== userId);
    return project;
  }

  /**
   * Check if a project exists
   */
  projectExists(id: string): boolean {
    return this.projects.has(id);
  }
}

export const projectService = new ProjectService();

/**
 * Task Service - Manages tasks within projects with status validation
 */

import { eventBus } from './event-bus';
import { projectService } from './project-service';
import { userService } from './user-service';

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export interface Task {
  id: string;
  projectId: string;
  title: string;
  description: string;
  status: TaskStatus;
  assignee: string | null; // User ID
}

const STATUS_ORDER: TaskStatus[] = ['todo', 'in-progress', 'done'];

function canTransition(from: TaskStatus, to: TaskStatus): boolean {
  const fromIndex = STATUS_ORDER.indexOf(from);
  const toIndex = STATUS_ORDER.indexOf(to);
  return fromIndex < toIndex;
}

export class TaskService {
  private tasks: Map<string, Task> = new Map();
  private nextId = 1;

  /**
   * Create a new task
   */
  createTask(
    projectId: string,
    title: string,
    description: string
  ): Task | null {
    // Verify project exists
    if (!projectService.projectExists(projectId)) return null;

    const id = `task-${this.nextId++}`;
    const task: Task = {
      id,
      projectId,
      title,
      description,
      status: 'todo',
      assignee: null,
    };
    this.tasks.set(id, task);

    eventBus.publish('task.created', {
      taskId: id,
      projectId,
      title,
    });

    return task;
  }

  /**
   * Get a task by ID
   */
  getTask(id: string): Task | null {
    return this.tasks.get(id) || null;
  }

  /**
   * Get all tasks
   */
  getAllTasks(): Task[] {
    return Array.from(this.tasks.values());
  }

  /**
   * Get tasks for a specific project
   */
  getTasksByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(
      (task) => task.projectId === projectId
    );
  }

  /**
   * Update a task
   */
  updateTask(id: string, updates: Partial<Task>): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    if (updates.title !== undefined) task.title = updates.title;
    if (updates.description !== undefined) task.description = updates.description;

    return task;
  }

  /**
   * Delete a task
   */
  deleteTask(id: string): boolean {
    return this.tasks.delete(id);
  }

  /**
   * Transition task status with validation
   */
  updateStatus(id: string, newStatus: TaskStatus): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    if (task.status === newStatus) {
      return task; // No change needed
    }

    if (!canTransition(task.status, newStatus)) {
      return null; // Invalid transition
    }

    const oldStatus = task.status;
    task.status = newStatus;

    eventBus.publish('task.status-changed', {
      taskId: id,
      projectId: task.projectId,
      oldStatus,
      newStatus,
      assignee: task.assignee,
    });

    return task;
  }

  /**
   * Assign a task to a user
   */
  assignTask(id: string, userId: string): Task | null {
    const task = this.tasks.get(id);
    if (!task) return null;

    // Verify user exists
    if (!userService.userExists(userId)) return null;

    const previousAssignee = task.assignee;
    task.assignee = userId;

    eventBus.publish('task.assigned', {
      taskId: id,
      projectId: task.projectId,
      assignee: userId,
      previousAssignee,
    });

    return task;
  }

  /**
   * Check if a task exists
   */
  taskExists(id: string): boolean {
    return this.tasks.has(id);
  }
}

export const taskService = new TaskService();

/**
 * Comment Service - Manages comments on tasks
 */

import { eventBus } from './event-bus';
import { taskService } from './task-service';
import { userService } from './user-service';

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  text: string;
  timestamp: number;
}

export class CommentService {
  private comments: Map<string, Comment> = new Map();
  private nextId = 1;

  /**
   * Add a comment to a task
   */
  addComment(taskId: string, authorId: string, text: string): Comment | null {
    // Verify task and user exist
    if (!taskService.taskExists(taskId)) return null;
    if (!userService.userExists(authorId)) return null;

    const id = `comment-${this.nextId++}`;
    const comment: Comment = {
      id,
      taskId,
      authorId,
      text,
      timestamp: Date.now(),
    };
    this.comments.set(id, comment);

    // Get the task to publish the event with assignee info
    const task = taskService.getTask(taskId);

    eventBus.publish('comment.added', {
      commentId: id,
      taskId,
      authorId,
      text,
      assignee: task?.assignee || null,
    });

    return comment;
  }

  /**
   * Get a comment by ID
   */
  getComment(id: string): Comment | null {
    return this.comments.get(id) || null;
  }

  /**
   * Get all comments
   */
  getAllComments(): Comment[] {
    return Array.from(this.comments.values());
  }

  /**
   * Get comments for a specific task
   */
  getCommentsByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values())
      .filter((comment) => comment.taskId === taskId)
      .sort((a, b) => a.timestamp - b.timestamp);
  }

  /**
   * Delete a comment
   */
  deleteComment(id: string): boolean {
    return this.comments.delete(id);
  }
}

export const commentService = new CommentService();

/**
 * Notification Service - Manages notifications and reacts to events
 */

import { eventBus } from './event-bus';
import { userService } from './user-service';
import { taskService } from './task-service';

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  timestamp: number;
}

export class NotificationService {
  private notifications: Map<string, Notification> = new Map();
  private nextId = 1;

  constructor() {
    this.setupEventSubscriptions();
  }

  /**
   * Setup event subscriptions
   */
  private setupEventSubscriptions(): void {
    // When a task is assigned
    eventBus.subscribe('task.assigned', (payload) => {
      const assignee = payload.assignee as string;
      const taskId = payload.taskId as string;
      const task = taskService.getTask(taskId);

      if (task) {
        const message = `You have been assigned to task: ${task.title}`;
        this.createNotification(assignee, message);
      }
    });

    // When task status changes
    eventBus.subscribe('task.status-changed', (payload) => {
      const assignee = payload.assignee as string | null;
      const newStatus = payload.newStatus as string;
      const taskId = payload.taskId as string;
      const task = taskService.getTask(taskId);

      if (assignee && task) {
        const message = `Task "${task.title}" status changed to: ${newStatus}`;
        this.createNotification(assignee, message);
      }
    });

    // When a comment is added
    eventBus.subscribe('comment.added', (payload) => {
      const assignee = payload.assignee as string | null;
      const taskId = payload.taskId as string;
      const authorId = payload.authorId as string;
      const author = userService.getUser(authorId);
      const task = taskService.getTask(taskId);

      if (assignee && author && task && assignee !== authorId) {
        const message = `${author.name} commented on task: ${task.title}`;
        this.createNotification(assignee, message);
      }
    });
  }

  /**
   * Create a notification
   */
  private createNotification(userId: string, message: string): Notification | null {
    // Verify user exists
    if (!userService.userExists(userId)) return null;

    const id = `notification-${this.nextId++}`;
    const notification: Notification = {
      id,
      userId,
      message,
      read: false,
      timestamp: Date.now(),
    };
    this.notifications.set(id, notification);
    return notification;
  }

  /**
   * Get a notification by ID
   */
  getNotification(id: string): Notification | null {
    return this.notifications.get(id) || null;
  }

  /**
   * Get all notifications
   */
  getAllNotifications(): Notification[] {
    return Array.from(this.notifications.values());
  }

  /**
   * Get notifications for a specific user
   */
  getNotificationsByUser(userId: string): Notification[] {
    return Array.from(this.notifications.values())
      .filter((notif) => notif.userId === userId)
      .sort((a, b) => b.timestamp - a.timestamp);
  }

  /**
   * Mark a notification as read
   */
  markAsRead(id: string): Notification | null {
    const notification = this.notifications.get(id);
    if (!notification) return null;

    notification.read = true;
    return notification;
  }

  /**
   * Delete a notification
   */
  deleteNotification(id: string): boolean {
    return this.notifications.delete(id);
  }
}

export const notificationService = new NotificationService();

/**
 * API Router - HTTP request routing and JSON handling
 */

import { IncomingMessage, ServerResponse } from 'http';
import { URL } from 'url';
import { userService } from './user-service';
import { projectService } from './project-service';
import { taskService } from './task-service';
import { commentService } from './comment-service';
import { notificationService } from './notification-service';

type RequestHandler = (
  req: IncomingMessage,
  res: ServerResponse,
  params: Record<string, string>
) => void;

interface Route {
  pattern: RegExp;
  methods: Record<string, RequestHandler>;
}

function parseJsonBody(req: IncomingMessage): Promise<Record<string, unknown>> {
  return new Promise((resolve, reject) => {
    let data = '';
    req.on('data', (chunk) => {
      data += chunk;
    });
    req.on('end', () => {
      try {
        resolve(data ? JSON.parse(data) : {});
      } catch (error) {
        reject(new Error('Invalid JSON'));
      }
    });
  });
}

function sendJson(
  res: ServerResponse,
  statusCode: number,
  data: unknown
): void {
  res.writeHead(statusCode, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify(data, null, 2));
}

function extractPathParams(
  pattern: RegExp,
  path: string
): Record<string, string> | null {
  const match = path.match(pattern);
  if (!match) return null;

  const params: Record<string, string> = {};
  const namedGroups = pattern.exec(path)?.groups || {};
  Object.assign(params, namedGroups);
  return params;
}

export class ApiRouter {
  private routes: Route[] = [];

  constructor() {
    this.setupRoutes();
  }

  /**
   * Setup all routes
   */
  private setupRoutes(): void {
    // Users routes
    this.addRoute(/^\/users\/?$/, 'GET', this.handleGetUsers);
    this.addRoute(/^\/users\/?$/, 'POST', this.handleCreateUser);
    this.addRoute(/^\/users\/(?<id>[^/]+)\/?$/, 'GET', this.handleGetUser);
    this.addRoute(/^\/users\/(?<id>[^/]+)\/?$/, 'PUT', this.handleUpdateUser);
    this.addRoute(/^\/users\/(?<id>[^/]+)\/?$/, 'DELETE', this.handleDeleteUser);

    // Projects routes
    this.addRoute(/^\/projects\/?$/, 'GET', this.handleGetProjects);
    this.addRoute(/^\/projects\/?$/, 'POST', this.handleCreateProject);
    this.addRoute(
      /^\/projects\/(?<id>[^/]+)\/?$/,
      'GET',
      this.handleGetProject
    );
    this.addRoute(
      /^\/projects\/(?<id>[^/]+)\/?$/,
      'PUT',
      this.handleUpdateProject
    );
    this.addRoute(
      /^\/projects\/(?<id>[^/]+)\/?$/,
      'DELETE',
      this.handleDeleteProject
    );
    this.addRoute(
      /^\/projects\/(?<id>[^/]+)\/members\/?$/,
      'POST',
      this.handleAddMember
    );
    this.addRoute(
      /^\/projects\/(?<id>[^/]+)\/members\/?$/,
      'DELETE',
      this.handleRemoveMember
    );

    // Tasks routes
    this.addRoute(/^\/tasks\/?$/, 'GET', this.handleGetTasks);
    this.addRoute(/^\/tasks\/?$/, 'POST', this.handleCreateTask);
    this.addRoute(/^\/tasks\/(?<id>[^/]+)\/?$/, 'GET', this.handleGetTask);
    this.addRoute(/^\/tasks\/(?<id>[^/]+)\/?$/, 'PUT', this.handleUpdateTask);
    this.addRoute(/^\/tasks\/(?<id>[^/]+)\/?$/, 'DELETE', this.handleDeleteTask);
    this.addRoute(
      /^\/tasks\/(?<id>[^/]+)\/status\/?$/,
      'PUT',
      this.handleUpdateTaskStatus
    );
    this.addRoute(
      /^\/tasks\/(?<id>[^/]+)\/assign\/?$/,
      'PUT',
      this.handleAssignTask
    );

    // Comments routes
    this.addRoute(/^\/comments\/?$/, 'GET', this.handleGetComments);
    this.addRoute(/^\/comments\/?$/, 'POST', this.handleAddComment);
    this.addRoute(/^\/comments\/(?<id>[^/]+)\/?$/, 'DELETE', this.handleDeleteComment);

    // Notifications routes
    this.addRoute(/^\/notifications\/?$/, 'GET', this.handleGetNotifications);
    this.addRoute(
      /^\/notifications\/(?<id>[^/]+)\/read\/?$/,
      'PUT',
      this.handleMarkNotificationRead
    );
  }

  /**
   * Add a route
   */
  private addRoute(
    pattern: RegExp,
    method: string,
    handler: RequestHandler
  ): void {
    let route = this.routes.find((r) => r.pattern.source === pattern.source);
    if (!route) {
      route = { pattern, methods: {} };
      this.routes.push(route);
    }
    route.methods[method] = handler;
  }

  /**
   * Handle incoming requests
   */
  async handleRequest(
    req: IncomingMessage,
    res: ServerResponse
  ): Promise<void> {
    const url = new URL(req.url || '/', `http://${req.headers.host}`);
    const pathname = url.pathname;
    const method = req.method || 'GET';

    // Find matching route
    for (const route of this.routes) {
      const params = extractPathParams(route.pattern, pathname);
      if (params !== null && route.methods[method]) {
        try {
          route.methods[method](req, res, params);
        } catch (error) {
          console.error('Error handling request:', error);
          sendJson(res, 500, { error: 'Internal server error' });
        }
        return;
      }
    }

    sendJson(res, 404, { error: 'Not found' });
  }

  // User handlers
  private handleGetUsers = (req: IncomingMessage, res: ServerResponse) => {
    const users = userService.getAllUsers();
    sendJson(res, 200, users);
  };

  private handleCreateUser = async (
    req: IncomingMessage,
    res: ServerResponse
  ) => {
    try {
      const body = (await parseJsonBody(req)) as {
        name?: string;
        email?: string;
      };
      if (!body.name || !body.email) {
        sendJson(res, 400, { error: 'Missing name or email' });
        return;
      }
      const user = userService.createUser(body.name, body.email);
      sendJson(res, 201, user);
    } catch (error) {
      sendJson(res, 400, { error: (error as Error).message });
    }
  };

  private handleGetUser = (
    req: IncomingMessage,
    res: ServerResponse,
    params: Record<string, string>
  ) => {
    const user = userService.getUser(params.id);
    if (!user) {
      sendJson(res, 404, { error: 'User not found' });
      return;
    }
    sendJson(res, 200, user);
  };

  private handleUpdateUser = async (
    req: IncomingMessage,
    res: ServerResponse,
    params: Record<string, string>
  ) => {
    try {
      const body = await parseJsonBody(req);
      const user = userService.updateUser(params.id, body as Partial<typeof userService>);
      if (!user) {
        sendJson(res, 404, { error: 'User not found' });
        return;
      }
      sendJson(res, 200, user);
    } catch (error) {
      sendJson(res, 400, { error: (error as Error).message });
    }
  };

  private handleDeleteUser = (
    req: IncomingMessage,
    res: ServerResponse,
    params: Record<string, string>
  ) => {
    const deleted = userService.deleteUser(params.id);
    if (!deleted) {
      sendJson(res, 404, { error: 'User not found' });
      return;
    }
    sendJson(res, 204, {});
  };

  // Project handlers
  private handleGetProjects = (req: IncomingMessage, res: ServerResponse) => {
    const projects = projectService.getAllProjects();
    sendJson(res, 200, projects);
  };

  private handleCreateProject = async (
    req: IncomingMessage,
    res: ServerResponse
  ) => {
    try {
      const body = (await parseJsonBody(req)) as {
        name?: string;
        description?: string;
      };
      if (!body.name) {
        sendJson(res, 400, { error: 'Missing name' });
        return;
      }
      const project = projectService.createProject(
        body.name,
        body.description || ''
      );
      sendJson(res, 201, project);
    } catch (error) {
      sendJson(res, 400, { error: (error as Error).message });
    }
  };

  private handleGetProject = (
    req: IncomingMessage,
    res: ServerResponse,
    params: Record<string, string>
  ) => {
    const project = projectService.getProject(params.id);
    if (!project) {
      sendJson(res, 404, { error: 'Project not found' });
      return;
    }
    sendJson(res, 200, project);
  };

  private handleUpdateProject = async (
    req: IncomingMessage,
    res: ServerResponse,
    params: Record<string, string>
  ) => {
    try {
      const body = await parseJsonBody(req);
      const project = projectService.updateProject(params.id, body as Partial<typeof projectService>);
      if (!project) {
        sendJson(res, 404, { error: 'Project not found' });
        return;
      }
      sendJson(res, 200, project);
    } catch (error) {
      sendJson(res, 400, { error: (error as Error).message });
    }
  };

  private handleDeleteProject = (
    req: IncomingMessage,
    res: ServerResponse,
    params: Record<string, string>
  ) => {
    const deleted = projectService.deleteProject(params.id);
    if (!deleted) {
      sendJson(res, 404, { error: 'Project not found' });
      return;
    }
    sendJson(res, 204, {});
  };

  private handleAddMember = async (
    req: IncomingMessage,
    res: ServerResponse,
    params: Record<string, string>
  ) => {
    try {
      const body = (await parseJsonBody(req)) as { userId?: string };
      if (!body.userId) {
        sendJson(res, 400, { error: 'Missing userId' });
        return;
      }
      const project = projectService.addMember(params.id, body.userId);
      if (!project) {
        sendJson(res, 404, { error: 'Project or user not found' });
        return;
      }
      sendJson(res, 200, project);
    } catch (error) {
      sendJson(res, 400, { error: (error as Error).message });
    }
  };

  private handleRemoveMember = async (
    req: IncomingMessage,
    res: ServerResponse,
    params: Record<string, string>
  ) => {
    try {
      const body = (await parseJsonBody(req)) as { userId?: string };
      if (!body.userId) {
        sendJson(res, 400, { error: 'Missing userId' });
        return;
      }
      const project = projectService.removeMember(params.id, body.userId);
      if (!project) {
        sendJson(res, 404, { error: 'Project not found' });
        return;
      }
      sendJson(res, 200, project);
    } catch (error) {
      sendJson(res, 400, { error: (error as Error).message });
    }
  };

  // Task handlers
  private handleGetTasks = (req: IncomingMessage, res: ServerResponse) => {
    const url = new URL(req.url || '/', `http://${req.headers.host}`);
    const projectId = url.searchParams.get('projectId');

    let tasks = taskService.getAllTasks();
    if (projectId) {
      tasks = tasks.filter((task) => task.projectId === projectId);
    }
    sendJson(res, 200, tasks);
  };

  private handleCreateTask = async (
    req: IncomingMessage,
    res: ServerResponse
  ) => {
    try {
      const body = (await parseJsonBody(req)) as {
        projectId?: string;
        title?: string;
        description?: string;
